-- EXPLICIT SQLITE TEST FIXTURE ONLY. Not production migrations.
CREATE TABLE IF NOT EXISTS kcrm_migrations (version TEXT PRIMARY KEY,checksum TEXT NOT NULL,applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS kcrm_users (id TEXT PRIMARY KEY,name TEXT NOT NULL,email TEXT NOT NULL COLLATE NOCASE UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1,session_version INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS kcrm_setup (id INTEGER PRIMARY KEY,owner_id TEXT REFERENCES kcrm_users(id),completed_at TEXT);
CREATE TABLE IF NOT EXISTS kcrm_auth_rate_limits (bucket TEXT PRIMARY KEY,window_started_at TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,blocked_until TEXT,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS kcrm_audit (id TEXT PRIMARY KEY,actor_id TEXT REFERENCES kcrm_users(id),action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,details TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS kcrm_partners (id TEXT PRIMARY KEY,name TEXT NOT NULL,kind TEXT NOT NULL,status TEXT NOT NULL,contact_name TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',website TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES kcrm_users(id),revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS kcrm_contacts (id TEXT PRIMARY KEY,partner_id TEXT NOT NULL REFERENCES kcrm_partners(id),name TEXT NOT NULL,role_title TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',email TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES kcrm_users(id),revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS kcrm_tasks (id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL,status TEXT NOT NULL,priority TEXT NOT NULL,assignee_id TEXT REFERENCES kcrm_users(id),partner_id TEXT REFERENCES kcrm_partners(id),due_date TEXT,completed_at TEXT,created_by TEXT NOT NULL REFERENCES kcrm_users(id),revision INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS kcrm_fixture_tasks_assignee ON kcrm_tasks(assignee_id,status,due_date);
